#[test]
fn test_an_artifact_and_an_image_and_a_box_only_path() {
    let pa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pts: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mk: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let im: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let m: i32 = mk_new(mk, 1, 1, 0, 0, -1, 0);
    let r: i32 = gt_path(pa, pa_rect(), pg_filled(), 0, -1, 0, 0, 4950, 20000, 5050);
    mk_set(mk, m, 6, 1);
    pa_set(pa, r, pf_mark(), m);
    crate::testport::assert_eq(gt_run(pa, pts, mk, im, gv_segments(), out), 1, "a path with no geometry is read by its box");
    crate::testport::assert_eq(gt_c(out, 0, 15) & gq_artifact_pagination(), gq_artifact_pagination(), "an /Artifact /Pagination mark is flagged");
    crate::testport::assert_eq(gt_c(out, 0, 2), -1, "a box-only candidate has no point");
    // a thin visible image placement is a rule of colour -1; a hidden one is nothing
    crate::port::cells_drop(pa, 0);
    let i: i32 = im_new(im, 1, 0, 0, 20000, 100, 5, 1, 1);
    crate::testport::assert_eq(gt_run(pa, pts, mk, im, gv_segments(), out), 1, "an image rule");
    crate::testport::assert_eq(gt_c(out, 0, 13), -1, "of unknown colour");
    crate::testport::assert_eq(gt_c(out, 0, 15), gq_from_image(), "flagged from-image");
    crate::testport::assert_eq(gt_run(pa, pts, mk, im, gv_legacy(), out), 0, "legacy has no image rules");
    im_set(im, i, mf_vis(), 5);
    crate::testport::assert_eq(gt_run(pa, pts, mk, im, gv_segments(), out), 0, "a hidden image is not one");
}
